<?php
/**
 * ChatHelp — apply-postversand — postversand.php ucunu sunucuya yazar/gunceller.
 *  Icerik base64 gomulu (sha1 dogrulamali). LetterXpress v1 setJob + getBalance
 *  + metinden gercek PDF uretimi (send_text). Kimlikler config.php'den okunur
 *  (bu betikte SIFRE YOK).
 * KULLANIM: pull2.php?key=...&files=apply-postversand.php
 */
header("Content-Type: text/plain; charset=UTF-8");
error_reporting(E_ERROR | E_PARSE);
echo "apply-postversand BASLADI OK (PHP ".PHP_VERSION.")\n\n";
$b64 = '';
$sha = "4f7e69c7f34308850193b5357f80f8672e0acaae";
$bin = base64_decode($b64);
if (sha1($bin)!==$sha) exit("  X icerik bozuk (sha1 uyusmuyor)\n");
$dest = __DIR__."/postversand.php";
$tmp = tempnam(sys_get_temp_dir(),"pv").".php";
file_put_contents($tmp,$bin);
$lo=[];$rc=0; exec("php -l ".escapeshellarg($tmp)." 2>&1",$lo,$rc); @unlink($tmp);
if($rc!==0){ echo "LINT HATASI:\n  ".implode("\n  ",$lo)."\n"; exit; }
if(is_file($dest)) @copy($dest,$dest.".bak-".date("Ymd-His"));
$w=@file_put_contents($dest,$bin);
$chk=(string)@file_get_contents($dest);
if($w===false || sha1($chk)!==$sha) exit("  X yazilamadi/dogrulanamadi\n");
echo "  OK postversand.php yazildi (".strlen($bin)." B, sha1 dogrulandi)\n\n";
echo "KONTROL: https://chat-help.com/chat/postversand.php?action=status\n";
echo "  configured:true + balance gormeli.\n";
